    for (i = 0; i < 4; i++) B.geo('leaf', GEO.sph, mtx(x + rand(-0.7, 0.7) * s, y + rand(2.5, 3.5) * s, z + rand(-0.7, 0.7) * s, rand(0, 3), rand(1.0, 1.4) * s), pick([0x3f9a3a, 0x52b148, 0x2e8a35, 0x66c24f]));
