function gesture(id) { P.gesture = { id: id, t: 0 }; logMsg('talk', '（' + (GESTURES.filter(function (g3) { return g3.id === id; })[0] || {}).n + '）', PLAYER.name); if (window.NET && NET.send) NET.send('ges', { g: id }); }
