    row('ＢＧＭ（音楽）', 'music', function () { return AUD.bgmOn; }, function (v) { audioSetBgm(v); });
    row('効果音', 'sound', function () { return AUD.sfxOn; }, function (v) { audioSetSfx(v); });
    row('軽量モード（古いスマホ用）', 'lite', function () { return LITE.on; }, function (v) { setLite(v); });
