    CS.descEl = el('div', 'desc', bd); CS.stEl = el('div', '', bd);
    var r = el('div', 'row2', bd); r.style.justifyContent = 'center';
    mbtn(r, '◀', function () { csShow(CS.idx - 1); });
    mbtn(r, change ? 'この人になる' : 'この人で始める', function () { csDecide(); }, 'gold');
    mbtn(r, '▶', function () { csShow(CS.idx + 1); });
