  CS.t += dt; if (CS.mesh) { CS.mesh.rotation.y += dt * 0.6; CS.mesh.position.y = Math.abs(Math.sin(CS.t * 2)) * 0.03; }
  var W = H.W, Hh = H.H, land = W > Hh;
