    if (f.spinning) { }
    else if (wantLook && dist > 0.5) { var ty = Math.atan2(dx, dz); m.rotation.y += angDiff(m.rotation.y, ty) * Math.min(1, dt * (f.statue ? 1 : 2.5)); }
