function findRecipe(a, b) { for (var i = 0; i < RECIPES.length; i++) { var r = RECIPES[i]; if ((r.a === a && r.b === b) || (r.a === b && r.b === a)) return r; } return null; }
// 形の情報（名前・説明・重さなど）
