  var b = it.body, o = it.obj;
  o.position.copy(b.pos); o.rotation.set(0, b.yaw, 0);
  if (b.roll) { it.pivot.rotation.set(b.rollA, 0, 0); }
  else it.pivot.rotation.set(b.rx, 0, b.rz);
